/* Public welcome page: illustrations and sample gift only. No account requests. */
(() => {
 'use strict';
 const P=window.PixelLove,M=window.LoveMotion,$=s=>document.querySelector(s);
 let selected='rabbit';
 const variants={rabbit:{outfit:'cardigan',hat:'bow',outfitColor:'#c48e9b'},cat:{outfit:'dress',hat:'beret',outfitColor:'#9da68c'},dog:{outfit:'overalls',hat:'bucket',outfitColor:'#a0b2bc'},pig:{outfit:'sailor',hat:'beret',outfitColor:'#bf8b99'},squirrel:{outfit:'cardigan',hat:'none',outfitColor:'#b5a0bc'}};
 function sample(id=selected){const a=P.animals.find(a=>a.id===id);return {...window.GiftSchema.defaults(),...variants[id],animal:id,name:a.nickname,bodyColor:a.color,flowers:[{id:'tulip',color:'#d990a6'},{id:'daisy',color:'#f3ded3'},{id:'rose',color:'#bc6684'}],wrapColor:'#e8d4b9',ribbonColor:'#ad6b81'};}
 const hero=$('#home-doll');
 P.draw(hero,sample());M?.mount(hero,()=>sample());
 document.querySelectorAll('[data-companion]').forEach(b=>{const id=b.dataset.companion;P.draw(b.querySelector('canvas'),{...sample(id),flowers:[]});b.addEventListener('click',()=>{selected=id;document.querySelectorAll('[data-companion]').forEach(other=>other.setAttribute('aria-pressed',String(other===b)));const a=P.animals.find(a=>a.id===id);$('#companion-name').textContent=a.nickname;hero.setAttribute('aria-label',a.nickname+' '+a.name+'ถือช่อดอกไม้');$('#companion-status').textContent='เลือก'+a.name+' '+a.nickname+'แล้ว';P.draw(hero,sample());M?.act(hero,'wave');});});
 P.draw($('#home-outfit'),{...sample('cat'),glasses:'heart',flowers:[]});const flowerContext=$('#home-flower').getContext('2d');flowerContext.imageSmoothingEnabled=false;flowerContext.save();flowerContext.translate(50,42);flowerContext.scale(1.1,1.1);flowerContext.translate(-116,-126);P.bouquet(flowerContext,{...sample('rabbit'),flowers:[{id:'tulip',color:'#d990a6'}]});flowerContext.restore();
 const dialog=$('#home-demo'),content=$('#demo-content');let stage=0,opening=false,timer;
 function renderDemo(){opening=false;content.classList.remove('opening');if(stage===0){content.innerHTML='<h2 id="demo-title">มีความในใจส่งถึงคุณ ♡</h2><p>คนคนหนึ่ง ฝากรอยยิ้มไว้ในซองนี้</p><div class="demo-theatre" aria-hidden="true"><div class="demo-envelope"><div class="envelope-paper">a little love, just for you.</div><div class="envelope-fold"></div><span>♥</span></div></div><button class="button primary-button demo-button" data-demo-next>เปิดซองจดหมาย ♡</button>';}
 else if(stage===1){content.innerHTML='<h2 id="demo-title">มีเจ้าตัวเล็กรอเจอคุณอยู่</h2><p>ค่อย ๆ แกะนะ เขาตั้งใจมาหาเลย</p><div class="demo-theatre" aria-hidden="true"><div class="demo-box"><div class="box-lid"></div><div class="box-bow"></div></div></div><button class="button primary-button demo-button" data-demo-next>เปิดกล่องของขวัญ ✧</button>';}
 else{content.innerHTML='<div class="demo-arrival"><h2 id="demo-title">ส่งกอดเล็ก ๆ มาให้คุณ</h2><canvas id="demo-doll" width="200" height="216" aria-label="ตุ๊กตาตัวอย่างถือช่อดอกไม้"></canvas><article class="demo-letter"><span>ถึง คนโปรดของเรา ♡</span><p>ขอบคุณที่เป็นความสบายใจในทุกวัน<br>อยู่เป็นรอยยิ้มให้กันไปนาน ๆ นะ</p></article><a class="button primary-button" href="/make?create=1">ทำของขวัญของคุณบ้าง</a><button class="demo-again" data-demo-again>เปิดของขวัญอีกครั้ง</button></div>';const c=$('#demo-doll'),s=sample();P.draw(c,s);M?.mount(c,()=>s);M?.act(c,'wave');M?.burst(content);}if(dialog.open)content.querySelector('button,a')?.focus();}
 document.querySelectorAll('[data-open-demo]').forEach(b=>b.addEventListener('click',()=>{stage=0;renderDemo();dialog.showModal();}));
 $('#close-demo').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{clearTimeout(timer);opening=false;});dialog.addEventListener('click',e=>{if(e.target.closest('[data-demo-again]')){stage=0;renderDemo();return;}const b=e.target.closest('[data-demo-next]');if(!b||opening)return;opening=true;b.disabled=true;b.textContent='กำลังเปิดความในใจ…';content.classList.add('opening');timer=setTimeout(()=>{if(dialog.open){stage++;renderDemo();}},M?.enabled?1100:0);});
})();
